<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Verify Sign In | Core 3</title><link rel="icon" type="image/svg+xml" href="assets/images/logo-icon.svg">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined" rel="stylesheet"><link href="assets/css/login.css?v=<?= time(); ?>" rel="stylesheet"></head>
<body class="auth-page"><main class="auth-shell"><section class="auth-card" aria-labelledby="mfaTitle"><header class="auth-heading"><div class="auth-brand-mark"><img src="assets/images/logo-icon.svg" alt="Great Solomon Manpower Services Inc."></div><h1 id="mfaTitle">Verify Sign In</h1><p>Enter the 6-digit code sent to <?= htmlspecialchars($masked_email); ?>.</p></header>
<div class="auth-error" id="alertBox" role="alert"><span class="material-symbols-outlined">error</span><span id="alertMsg"></span></div>
<form id="mfaForm" class="auth-form"><?= csrf_input(); ?><label for="otp">Verification Code</label><div class="auth-input"><span class="material-symbols-outlined">password</span><input type="text" id="otp" name="otp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" placeholder="000000" required></div><button type="submit" class="auth-submit" id="verifyButton">Verify and Continue</button></form>
<div class="auth-options"><a href="#" class="auth-link" id="resendLink">Resend code</a><a href="index.php?page=login" class="auth-link">Back to sign in</a></div><footer class="auth-footer"><p>Codes expire after <?= MFA_OTP_TTL_MINUTES; ?> minutes and can only be used once.</p></footer></section></main>
<script>
const form=document.getElementById('mfaForm'),alertBox=document.getElementById('alertBox'),alertMsg=document.getElementById('alertMsg'),button=document.getElementById('verifyButton'),resend=document.getElementById('resendLink');
function show(message){alertMsg.textContent=message;alertBox.style.display='flex'}
async function send(url,data){const response=await fetch(url,{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json','Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)});return response.json()}
form.addEventListener('submit',async event=>{event.preventDefault();alertBox.style.display='none';button.disabled=true;try{const result=await send('index.php?page=mfa_verify',Object.fromEntries(new FormData(form)));if(result.status==='success'||result.data?.redirect)location.href=result.data.redirect;else show(result.message)}catch(e){show('Connection error. Please try again.')}finally{button.disabled=false}});
resend.addEventListener('click',async event=>{event.preventDefault();resend.style.pointerEvents='none';try{const result=await send('index.php?page=mfa_resend',{csrf_token:form.querySelector('[name=csrf_token]').value});show(result.message);if(result.data?.redirect)location.href=result.data.redirect}catch(e){show('Connection error. Please try again.')}finally{setTimeout(()=>resend.style.pointerEvents='',1000)}});
</script></body></html>
